function releases(c){if(!c.releases.length)return `<div class="empty">♫<strong>Nothing out in the world. Yet.</strong>Your debut is just one song away.</div>`;return `<div class="release-list">${c.releases.slice(-4).reverse().map((r,i)=>`<div class="release-item"><div class="cover">${r.type==='Album'?'💿':'♫'}</div><div class="release-info"><strong>${r.title}</strong><small>${r.type} · ${r.genre} · ${r.streams.toLocaleString()} streams</small></div><div class="release-rank">${r.rank?`#${r.rank}`:'—'}</div></div>`).join('')}</div>`}
function dashboard(c){return `${pageHead('Your next chapter','The city is listening. What will you do with this week?',`<button class="btn btn-dark" data-action="advance">Advance week <span>→</span></button>`)}<div class="grid stats-grid">${stat('POPULARITY',c.popularity+' / 100','↗ Building your audience')}${stat('CAREER STATUS',c.level,'Independent')}${stat('CASH',money(c.cash),'Available balance')}${stat('NET WORTH',money(c.net),'↗ Your empire, growing')}</div><div class="grid dashboard-grid"><div><div class="card hero-card"><div class="hero-text"><span class="pill"><span class="dot"></span> ON THE RISE</span><h2>Make them<br>remember your name.</h2><p>${c.first} ${c.last} is ready for the next big moment. Keep creating, keep showing up.</p><button class="btn btn-dark btn-small" data-section="Character">Customize character →</button></div><div class="avatar-wrap">${avatar(c)}</div></div><div class="card card-pad" style="margin-top:16px"><div class="section-title"><h3>Latest releases</h3><a data-section="Music">VIEW DISCOGRAPHY →</a></div>${releases(c)}</div></div><div class="grid" style="align-content:start"><div class="card career-card"><div class="section-title"><h3>Career overview</h3><span class="tag">${c.level}</span></div><div class="career-status"><strong>${c.popularity<25?'Finding your sound':c.popularity<55?'Rising artist':'Breakthrough act'}</strong><span class="eyebrow">${c.popularity}%</span></div><div class="progress"><span style="width:${c.popularity}%"></span></div><div class="metrics-row"><span>Popularity</span><span>${c.releases.length} release${c.releases.length===1?'':'s'} · ${c.location}</span></div><div style="margin-top:18px" class="section-title"><h3>Upcoming opportunities</h3><a data-section="Business">EXPLORE →</a></div><div class="feed-item"><div class="feed-icon">◈</div><div><strong>Open mic at The Low Note</strong><small>Perform this week · +fans, +heat</small></div><button class="btn btn-light btn-small" data-action="gig">Go</button></div><div class="feed-item"><div class="feed-icon">♫</div><div><strong>Studio time is waiting</strong><small>Record your next release</small></div><button class="btn btn-light btn-small" data-section="Music">Go</button></div></div><div class="card card-pad"><div class="section-title"><h3>Industry wire</h3><a data-section="Industry">ALL NEWS →</a></div><div class="feed">${feedItems(c)}</div></div></div></div>`}
function musicPage(c){return `${pageHead('The music','Write a song, shape a sound, and put it out into the world.',`<button class="btn btn-purple" data-action="write">＋ Create a song</button>`)}<div class="grid two-col"><div class="card card-pad"><div class="section-title"><h3>Recording studio</h3><span class="tag">${c.energy}% ENERGY</span></div><p style="color:var(--muted);font-size:12px;line-height:1.6">Every great record starts with an idea. Spend a little energy, find your sound, and release a single or build a full-length album.</p><div class="grid two-col" style="margin-top:18px"><button class="btn btn-purple" data-action="write">♫ Write a single</button><button class="btn btn-light" data-action="album">💿 Record an album</button></div><div class="metrics-row"><span>Singles earn buzz quickly</span><span>Album costs $1,200</span></div></div><div class="card card-pad"><div class="section-title"><h3>Your discography</h3><span class="eyebrow">${c.releases.length} RELEASES</span></div>${releases(c)}</div></div><div class="grid two-col" style="margin-top:16px"><div class="card card-pad"><div class="section-title"><h3>Make connections</h3><span class="eyebrow">COLLABORATIONS</span></div><p style="color:var(--muted);font-size:12px;line-height:1.6">Work with another artist and your music reaches a whole new audience.</p><button class="btn btn-light btn-small" data-action="collab">Invite a collaborator · $250</button></div><div class="card card-pad"><div class="section-title"><h3>Producers</h3><span class="eyebrow">IN THE STUDIO</span></div><div class="release-item"><div class="cover">🎛️</div><div class="release-info"><strong>Rae “Daybreak” Kim</strong><small>Indie pop · $400 session</small></div><button class="btn btn-light btn-small" data-action="producer">Book</button></div></div></div>`}
function chartRows(c){let rows=[...c.charts];for(const r of c.releases)rows.push({name:c.stage,genre:r.genre,score:Math.min(98,40+r.streams/10000),delta:0,title:r.title,player:true});return rows.sort((a,b)=>b.score-a.score).slice(0,20).map((a,i)=>`<tr><td class="rank">${String(i+1).padStart(2,'0')}</td><td><div class="artist"><span class="artist-dot" style="${a.player?'background:#e8e4ff;color:#5948bc':''}">${a.player?'✦':a.name[0]}</span>${a.player?c.stage:a.name}${a.player?' <span class="tag">YOU</span>':''}</div></td><td>${a.title}</td><td><span class="tag">${a.genre}</span></td><td><div class="chart-bar"><i style="width:${a.score}%"></i></div></td><td class="${a.delta<0?'negative':'change'}">${a.delta>0?'▲ '+a.delta:a.delta<0?'▼ '+Math.abs(a.delta):'NEW'}</td></tr>`).join('')}
function chartsPage(c){return `${pageHead('The charts','A living snapshot of the songs moving the culture.',`<span class="pill">WEEK ${c.week} · ${c.year}</span>`)}<div class="grid stats-grid">${stat('HOT 100 TRACKS','100','Across every genre')}${stat('NEW ENTRIES',''+(2+c.week%5),'This week')}${stat('BIGGEST CLIMBER','↑ 18','“Blue Hour” · Nico Vale')}${stat('YOUR BEST',''+(c.releases.length?'#'+(Math.max(1,30-c.popularity)):'—'),'Hot 100 position')}</div><div class="card card-pad"><div class="section-title"><div><h3>Billboard Hot 100</h3><span class="eyebrow">UPDATED EVERY WEEK · ALL ARTISTS COMPETE</span></div><span class="tag">GLOBAL</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>POS</th><th>ARTIST</th><th>SONG</th><th>GENRE</th><th>BUZZ</th><th>MOVE</th></tr></thead><tbody>${chartRows(c)}</tbody></table></div></div><div class="grid two-col" style="margin-top:16px"><div class="card card-pad"><div class="section-title"><h3>Genre charts</h3></div><div class="feed-item"><div class="feed-icon">♫</div><div><strong>Top R&B songs</strong><small>Maya Sol · “Midnight Drive” is #1</small></div></div><div class="feed-item"><div class="feed-icon">♬</div><div><strong>Hip-hop top 50</strong><small>Jett Monroe leads this week</small></div></div><div class="feed-item"><div class="feed-icon">✧</div><div><strong>Global 200</strong><small>Streaming across 42 markets</small></div></div></div><div class="week-card"><div class="eyebrow">THE LONG GAME</div><h3>Hits don't happen overnight.</h3><p>Each week, songs move with buzz, releases, and a little unpredictability. A song can find its moment long after release.</p><button class="btn btn-lime btn-small" data-action="advance">See what happens →</button></div></div>`}

