function releaseModal(type){let album=type==='Album';modal(album?'Record an album':'Create a song',album?'A full-length statement. $1,200 studio cost.':'Write your next single and find out where it takes you.',`<form id="releaseForm"><div class="form-grid"><div class="field full"><label>${album?'Album':'Song'} title</label><input name="title" placeholder="Give it a name" maxlength="36" required></div><div class="field"><label>Genre</label><select name="genre">${['Pop','R&B','Hip-hop','Alternative','Rock','Country','Dance','Soul','Indie'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Release type</label><select name="type"><option>Single</option><option>EP</option>${album?'<option selected>Album</option>':''}</select></div><div class="field full"><label>Sound / era</label><select name="era"><option>Contemporary</option><option>Vintage soul</option><option>70s warmth</option><option>80s synth-pop</option><option>90s alternative</option><option>2000s pop</option><option>Future-facing</option></select></div></div></form>`,`<button class="btn btn-light" data-action="close">Cancel</button><button class="btn btn-purple" data-action="release">Release to the world →</button>`)}
function say(message){let t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function news(c,title,icon='♫'){c.feed.push({title,icon,time:`Industry wire · ${c.year}, week ${c.week}`});if(c.feed.length>15)c.feed.shift()}
function advance(){let c=getSave();c.week++;if(c.week>52){c.week=1;c.year++}c.energy=Math.min(100,c.energy+35);let movers=[];c.charts.forEach(a=>{let old=a.score;a.score=Math.max(8,Math.min(96,a.score+(Math.random()*10-4)+(a.score>60?-1:0)));a.delta=Math.round(a.score-old)});if(Math.random()<.42){let acts=[['Rico Lunar','Hip-hop'],['Amara Bloom','R&B'],['Sunday Cinema','Alternative'],['Saint June','Pop'],['The Violet Hours','Rock']];let a=acts[Math.floor(Math.random()*acts.length)];c.charts.unshift({name:a[0],genre:a[1],score:48+Math.random()*30,delta:0,title:['Open Water','Run It Back','Soft Landing','Big Feelings','Night Shift'][Math.floor(Math.random()*5)]});news(c,`${a[0]} drops a surprise new track and shakes up the charts.`,'♫')}c.charts=c.charts.slice(0,20);let earnings=0;c.releases.forEach(r=>{let streams=Math.max(200,Math.floor((r.buzz*1100+Math.random()*7000)/(c.week-r.week+1)));r.streams+=streams;earnings+=Math.floor(streams*.006);r.buzz=Math.max(5,r.buzz+(Math.random()*5-2))});if(earnings){c.cash+=earnings;c.net+=earnings}c.heat=Math.max(0,Math.min(99,c.heat+Math.round(Math.random()*7-2)));if(c.releases.length&&Math.random()<.45){let headlines=['A late-night playlist gives '+c.stage+' a boost.',''+c.stage+' is gaining momentum with listeners.','Fans are asking when '+c.stage+' will drop another record.'];news(c,headlines[Math.floor(Math.random()*headlines.length)],'✦')}else if(Math.random()<.6){let headlines=['Legendary R&B singer announces retirement.','Rising hip-hop artist signs a major record deal.','Superstar releases a highly anticipated album.','Two artists engage in a public rivalry.','Independent artist reaches the Billboard Hot 100.','A record label announces a massive expansion.'];news(c,headlines[Math.floor(Math.random()*headlines.length)],'◎')}persist();render();say(`Week ${c.week} begins. Energy restored.${earnings?` You earned ${money(earnings)} from streams.`:''}`)}
