/* Encore V1 systems layer. Kept separate so existing saves and the original UI remain compatible. */
const V1_ERA_ARTISTS=[
 {start:1970,end:1979,artists:[['Stevie Wonder','Soul'],['Aretha Franklin','Soul'],['Marvin Gaye','Soul'],['Donna Summer','Disco'],['Chic','Funk'],['Earth, Wind & Fire','Funk'],['Bob Marley','Reggae']]},
 {start:1980,end:1989,artists:[['Michael Jackson','Pop'],['Prince','Pop'],['Whitney Houston','R&B'],['Janet Jackson','R&B'],['Run-D.M.C.','Hip-hop'],['Sade','Soul'],['Madonna','Pop']]},
 {start:1990,end:1999,artists:[['Mariah Carey','R&B'],['Tupac Shakur','Hip-hop'],['The Notorious B.I.G.','Rap'],['Mary J. Blige','R&B'],['Aaliyah','R&B'],['D’Angelo','Neo-soul'],['TLC','R&B']]},
 {start:2000,end:2009,artists:[['Beyoncé','R&B'],['Alicia Keys','Soul'],['Usher','R&B'],['Kanye West','Hip-hop'],['Rihanna','Pop'],['OutKast','Hip-hop'],['Missy Elliott','Rap']]},
 {start:2010,end:2019,artists:[['Drake','Hip-hop'],['Frank Ocean','Alternative R&B'],['Adele','Pop'],['Kendrick Lamar','Rap'],['The Weeknd','R&B'],['Bruno Mars','Pop'],['J. Cole','Hip-hop']]},
 {start:2020,end:2029,artists:[['SZA','R&B'],['Bad Bunny','Pop'],['Burna Boy','Afrobeats'],['Olivia Rodrigo','Pop'],['Taylor Swift','Pop'],['Doja Cat','Rap'],['Tems','R&B']]}
];
const V1_REG_NAMES=['Ari Sol','Milo June','Kira North','The Paper Moons','Juno Vale','Rae Wilder','Noah Bloom','Velvet Radio','Cleo Parks','Dante Blue','Sunday Arcade','Lio Rivers'];
const V1_GENRES=['R&B','Soul','New jack swing','Hip-hop','Rap','Funk','Disco','Pop','Neo-soul','Alternative R&B','Gospel','Rock','Jazz','Country','Reggae','Afrobeats'];
const V1_ASSETS={
 'First apartment':{value:12000,rent:0},'Vintage convertible':{value:24000,rent:0},'Home studio':{value:6500,rent:0},'City loft':{value:75000,rent:0},'Tour van':{value:18000,rent:0},'Weekend escape':{value:130000,rent:0},
 'Studio apartment':{value:45000,rent:450},'Suburban home':{value:185000,rent:1100},'Recording studio':{value:275000,rent:0},'Hillside estate':{value:1250000,rent:6500},'1970 Chevrolet Chevelle':{value:28000,rent:0},'1984 Mercedes-Benz 500 SEC':{value:36000,rent:0},'Tour bus':{value:160000,rent:0},'Private jet share':{value:850000,rent:0}
};
function v1Era(year){return V1_ERA_ARTISTS.find(x=>year>=x.start&&year<=x.end)||V1_ERA_ARTISTS.at(-1)}
function v1Migrate(){slots.forEach(c=>{c.energy=Number.isFinite(c.energy)?c.energy:100;c.heat=Number.isFinite(c.heat)?c.heat:10;c.releases=Array.isArray(c.releases)?c.releases:[];c.feed=Array.isArray(c.feed)?c.feed:[];c.owned=Array.isArray(c.owned)?c.owned:[];c.assets=Array.isArray(c.assets)?c.assets:[];c.relationships=c.relationships||{};c.roster=Array.isArray(c.roster)?c.roster:[];c.groups=Array.isArray(c.groups)?c.groups:[];c.label=c.label||null;c.weeklyReport=c.weeklyReport||null;c.settings=c.settings||{};c.releases.forEach(r=>{r.year=r.year||c.year;r.week=r.week||1;r.streams=Number(r.streams)||0;r.buzz=Number(r.buzz)||20});});persist()}
function v1Net(c){let property=(c.assets||[]).reduce((n,name)=>n+(V1_ASSETS[name]?.value||0),0),wardrobe=(c.owned||[]).reduce((n,id)=>n+(catalog[id]?.[3]||0)*.5,0),label=(c.label?Math.max(0,c.label.value||5000):0);c.net=Math.max(0,Math.floor((Number(c.cash)||0)+property+wardrobe+label));return c.net}
function v1AddFeed(c,title,icon='♫'){news(c,title,icon)}
function v1RosterFor(year){let list=v1Era(year).artists;return list.map((a,i)=>({name:a[0],genre:a[1],score:91-i*5+Math.random()*5,title:['Golden Hour','Afterglow','Electric Heart','Blue Note','Open Road','Night Bloom','Homecoming'][i%7],delta:0,artist:true}))}
function v1KnownCharts(c){let names=new Set(v1Era(c.year).artists.map(a=>a[0]));return c.charts.filter(x=>x.player||names.has(x.name))}
const v1BaseAdvance=advance;
advance=function(){let c=getSave();if(!c)return;const wasYear=c.year,prev=c.week;c.week++;if(c.week>52){c.week=1;c.year++}c.energy=Math.min(100,(c.energy||0)+45);if(c.year!==wasYear){let oldNames=new Set(v1Era(wasYear).artists.map(a=>a[0]));c.charts=c.charts.filter(x=>x.player||!oldNames.has(x.name));c.charts.push(...v1RosterFor(c.year));v1AddFeed(c,`A new decade begins. ${v1Era(c.year).artists[0][0]} is among the names shaping the sound.`,'◎')}
 let earnings=0,streamLines=[];c.releases.forEach(r=>{let ageWeeks=Math.max(1,(c.year-(r.year||c.year))*52+c.week-(r.week||1)+1),decay=Math.pow(.965,ageWeeks-1),base=Math.max(60,Math.floor((r.buzz*95+Math.random()*900)*decay));if(r.campaignWeeks>0){base=Math.floor(base*1.65);r.campaignWeeks--}r.streams=(Number(r.streams)||0)+base;let cut=c.label?.deal==='Major'?0.55:c.label?.deal==='Distribution'?0.9:1;let revenue=Math.floor(base*.006*cut);earnings+=revenue;streamLines.push(`${r.title}: +${base.toLocaleString()}`);r.buzz=Math.max(4,r.buzz+(Math.random()*4-2))});
 let rent=(c.assets||[]).reduce((n,name)=>n+(V1_ASSETS[name]?.rent||0),0),rosterPay=(c.roster||[]).reduce((n,a)=>n+(a.weeklyCost||75),0);let labelIncome=(c.roster||[]).reduce((n,a)=>n+Math.floor((a.popularity||25)*2),0);let expenses=rent+rosterPay;c.cash+=earnings+labelIncome-expenses;
 c.heat=Math.max(0,Math.min(99,(c.heat||0)+Math.floor(Math.random()*7-2)));c.popularity=Math.max(0,Math.min(100,(c.popularity||0)+(earnings>300?1:0)));(c.charts||[]).forEach(a=>{let old=a.score;a.score=Math.max(4,Math.min(98,a.score+(Math.random()*8-3.5)+(a.score>75?-1:0)));a.delta=Math.round(a.score-old)});
 if(Math.random()<.30){let reg=V1_REG_NAMES[Math.floor(Math.random()*V1_REG_NAMES.length)],genre=V1_GENRES[Math.floor(Math.random()*V1_GENRES.length)];if(!c.charts.some(x=>x.name===reg))c.charts.push({name:reg,genre,score:42+Math.random()*35,title:['New Light','Run It Back','Soft Landing','Big Feelings','Night Shift'][Math.floor(Math.random()*5)],delta:0,reg:true})}
 c.charts=c.charts.filter(x=>!x.player);c.releases.forEach(r=>{let score=Math.min(98,22+r.buzz+Math.log10(Math.max(1,r.streams))*2);c.charts.push({name:c.stage,genre:r.genre,score,title:r.title,delta:r.delta||0,player:true,releaseId:r.id})});c.charts.sort((a,b)=>b.score-a.score);c.charts=c.charts.slice(0,35);c.releases.forEach(r=>{let i=c.charts.findIndex(x=>x.player&&x.releaseId===r.id);r.rank=i<0?0:i+1});
 Object.values(c.relationships).forEach(rel=>{if(rel.score>0)rel.score=Math.max(0,rel.score-(Math.random()<.2?1:0))});let report={year:c.year,week:c.week,streams:streamLines,earnings,expenses,net:earnings+labelIncome-expenses,energy:c.energy,event:null};let events=[['A local radio host wants to champion your next record.','radio'],['A rival artist calls you out in an interview.','rival'],['A community benefit asks you to perform.','benefit'],['A producer offers a discounted studio session.','studio']];if(Math.random()<.23){let event=events[Math.floor(Math.random()*events.length)];report.event=event[0];c.pendingEvent=event[1]}
 c.weeklyReport=report;if(earnings+labelIncome-expenses!==0)v1AddFeed(c,`Weekly books: ${money(earnings+labelIncome)} income, ${money(expenses)} costs.`,'◈');if(c.pendingEvent)v1AddFeed(c,report.event,'✦');if(c.releases.length&&Math.random()<.5)v1AddFeed(c,`${c.stage} now has ${c.releases.reduce((n,r)=>n+r.streams,0).toLocaleString()} lifetime streams.`,'♫');v1Net(c);persist();render();say(`Week ${c.week} · ${money(earnings+labelIncome-expenses)} net this week. Energy restored.`);if(c.pendingEvent)v1EventModal(c.pendingEvent)};
function v1EventModal(type){let content,actions;if(type==='radio'){content='A regional radio host wants to put your latest track in rotation. Pay for a short promotional push?';actions='<button class="btn btn-light" data-action="event-decline">Pass</button><button class="btn btn-purple" data-action="event-radio">Pay $300 · accept</button>'}else if(type==='rival'){content='A chart rival took a public shot at your sound. How do you respond?';actions='<button class="btn btn-light" data-action="event-ignore">Stay above it</button><button class="btn btn-purple" data-action="event-clapback">Clap back · +heat</button>'}else if(type==='benefit'){content='A community benefit invites you to perform. Show up for the cause?';actions='<button class="btn btn-light" data-action="event-decline">Pass</button><button class="btn btn-purple" data-action="event-benefit">Perform · 15 energy</button>'}else{content='A producer offers a discounted session for your next song.';actions='<button class="btn btn-light" data-action="event-decline">Pass</button><button class="btn btn-purple" data-action="event-studio">Book · $250</button>'}modal('A moment in the week',content,`<p style="line-height:1.6;color:var(--muted)">${content}</p>`,actions)}
function v1BusinessPanel(c){let roster=c.roster||[];return `<div class="grid two-col" style="margin-top:16px"><div class="card card-pad"><div class="section-title"><h3>${c.label?c.label.name:'Build a label'}</h3><span class="tag">${c.label?c.label.deal+' · OWNED':'INDEPENDENT'}</span></div><p style="color:var(--muted);font-size:12px;line-height:1.6">${c.label?'Your imprint signs talent and earns a share of their weekly momentum.':'Start an imprint to sign artists, build a roster, and develop your own sound.'}</p>${c.label?`<button class="btn btn-light btn-small" data-action="sign-artist">＋ Sign an artist · $1,000</button>`:`<button class="btn btn-purple btn-small" data-action="found-label">Found a label · $5,000</button>`}<div class="release-list" style="margin-top:12px">${roster.length?roster.map(a=>`<div class="release-item"><div class="cover">♫</div><div class="release-info"><strong>${a.name}</strong><small>${a.genre} · ${a.popularity} popularity · ${money(a.weeklyCost||75)}/week support</small></div><span class="tag">SIGNED</span></div>`).join(''):'<div class="empty">Your roster is waiting for its first voice.</div>'}</div></div><div class="card card-pad"><div class="section-title"><h3>Groups & crews</h3><span class="tag">${(c.groups||[]).length} GROUP${(c.groups||[]).length===1?'':'S'}</span></div><p style="color:var(--muted);font-size:12px;line-height:1.6">Bring artists together under one name. Groups create new collaboration opportunities.</p><button class="btn btn-light btn-small" data-action="form-group">＋ Form a group</button>${(c.groups||[]).map(g=>`<div class="feed-item"><div class="feed-icon">♬</div><div><strong>${g.name}</strong><small>${g.members.join(' · ')}</small></div></div>`).join('')}</div></div>`}
function v1SocialPanel(c){let names=v1Era(c.year).artists.slice(0,5).map(x=>x[0]);return `<div class="card card-pad" style="margin-top:16px"><div class="section-title"><h3>Relationships & rivalries</h3><span class="eyebrow">A LIVING INDUSTRY</span></div><div class="grid three-col">${names.map((name,i)=>{let r=c.relationships[name]||{score:0,rival:false};return `<div class="feed-item"><div class="artist-dot">${name[0]}</div><div><strong>${name}</strong><small>${r.rival?'Rivalry':r.score>0?'Connection':'Acquaintance'} · ${r.score||0} rapport</small></div><button class="btn btn-light btn-small" data-action="relationship" data-name="${name}" data-rival="${i===1}">${r.rival?'Reconcile':r.score>0?'Collaborate':'Connect'}</button></div>`}).join('')}</div></div>`}
const v1BaseBusiness=businessPage;
businessPage=function(c){return v1BaseBusiness(c)+v1BusinessPanel(c)};
const v1BaseIndustry=industryPage;
industryPage=function(c){return v1BaseIndustry(c)+v1SocialPanel(c)};
const v1BaseCharts=chartRows;
chartRows=function(c){let rows=[...c.charts];return rows.sort((a,b)=>b.score-a.score).slice(0,20).map((a,i)=>`<tr><td class="rank">${String(i+1).padStart(2,'0')}</td><td><div class="artist"><span class="artist-dot" style="${a.player?'background:#e8e4ff;color:#5948bc':''}">${a.player?'✦':a.name[0]}</span>${a.player?c.stage:a.name}${a.player?' <span class="tag">YOU</span>':''}</div></td><td>${a.title}</td><td><span class="tag">${a.genre}</span></td><td><div class="chart-bar"><i style="width:${Math.max(0,Math.min(100,a.score))}%"></i></div></td><td class="${a.delta<0?'negative':'change'}">${a.delta>0?'▲ '+a.delta:a.delta<0?'▼ '+Math.abs(a.delta):'NEW'}</td></tr>`).join('')};
const v1BaseDashboard=dashboard;
dashboard=function(c){let report=c.weeklyReport,block=report?`<div class="card card-pad" style="margin-top:16px"><div class="section-title"><h3>Last week · ${report.year}, week ${report.week}</h3><span class="tag">${money(report.net)} NET</span></div><div class="metrics-row"><span>Streaming & label income ${money(report.earnings||0)}</span><span>Living & roster costs ${money(report.expenses||0)}</span></div>${report.streams?.length?`<div class="feed-item"><div class="feed-icon">♫</div><div><strong>${report.streams.slice(0,3).join(' · ')}</strong><small>Weekly streaming report</small></div></div>`:''}</div>`:'';return v1BaseDashboard(c)+block};
const v1BaseReleaseModal=releaseModal;
releaseModal=function(type){let album=type==='Album';modal(album?'Record an album':'Create a song',`Configure your ${album?'album':'release'} for the current era. Studio cost starts at $${album?'1,200':'200'}.`,`<form id="releaseForm"><div class="form-grid"><div class="field full"><label>${album?'Album':'Song'} title</label><input name="title" placeholder="Give it a name" maxlength="36" required></div><div class="field"><label>Genre</label><select name="genre">${V1_GENRES.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Release type</label><select name="type"><option>Single</option><option>EP</option>${album?'<option selected>Album</option>':''}</select></div><div class="field"><label>Promotion budget</label><select name="promo"><option value="0">No campaign · free</option><option value="350">Local press · $350</option><option value="1200">National campaign · $1,200</option></select></div><div class="field"><label>Sound / era</label><select name="era"><option>Contemporary</option><option>Vintage soul</option><option>70s warmth</option><option>80s synth-pop</option><option>90s alternative</option><option>2000s pop</option><option>Future-facing</option></select></div><div class="field full"><label>Release strategy</label><select name="strategy"><option value="steady">Steady build · balanced</option><option value="viral">Short-form push · high variance</option><option value="radio">Radio-first · slower, lasting</option></select></div></div></form>`,`<button class="btn btn-light" data-action="close">Cancel</button><button class="btn btn-purple" data-action="release">Release to the world →</button>`)};
const v1BaseCommitRelease=commitRelease;
commitRelease=function(){let c=getSave(),f=$('#releaseForm');if(!f?.reportValidity())return;let d=Object.fromEntries(new FormData(f)),cost=(d.type==='Album'?1200:d.type==='EP'?500:200)+(+d.promo||0);if(c.energy<20){say('You need 20 energy. Advance a week to rest.');return}if(c.cash<cost){say(`This release needs ${money(cost)}. Choose a smaller campaign or build your balance.`);return}c.cash-=cost;c.energy-=20;c.heat=Math.min(99,c.heat+8);c.popularity=Math.min(100,c.popularity+4+Math.floor(Math.random()*5));c.level=c.popularity>60?'Breakthrough artist':c.popularity>25?'Rising artist':'Independent artist';let strategy={steady:1,viral:1.35,radio:.9}[d.strategy]||1;let r={id:`${c.id}-${c.year}-${c.week}-${Date.now()}`,title:d.title,genre:d.genre,type:d.type,era:d.era,streams:0,buzz:(20+c.popularity+Math.random()*20)*strategy,week:c.week,year:c.year,rank:0,campaignWeeks:+d.promo?3:0,strategy:d.strategy};c.releases.push(r);v1AddFeed(c,`${c.stage} releases “${r.title},” a ${d.era.toLowerCase()} ${r.genre} ${d.type.toLowerCase()}.`,'♫');v1Net(c);persist();$('#modal').remove();section='Overview';render();say('It’s out in the world. The charts are listening.')};
function v1CreateModal(){createModal();let year=$('#careerForm [name="year"]');if(year){year.innerHTML=[1970,1971,1972,1973,1974,1975,1976,1977,1978,1979,...[1980,1990,2000,2010,2020,2024]].map(y=>`<option ${y===2024?'selected':''}>${y}</option>`).join('')}}
const v1BaseAction=handleAction;
handleAction=function(a,el){let c=getSave();if(a==='create'){v1CreateModal();return}if(!c)return;
 if(a==='found-label'){if(c.label){say('You already own an imprint.');return}if(c.cash<5000){say('Founding an imprint costs $5,000.');return}c.cash-=5000;c.label={name:`${c.stage} Records`,deal:'Independent',value:5000};v1AddFeed(c,`${c.stage} launches ${c.label.name}.`,'◈');v1Net(c);persist();render();say('Your label is open for business.');return}
 if(a==='sign-artist'){if(!c.label){say('Found a label before signing talent.');return}if((c.roster||[]).length>=5){say('Your independent roster is full (5 artists).');return}if(c.cash<1000){say('Signing an artist requires a $1,000 development advance.');return}let candidates=V1_REG_NAMES.filter(n=>!c.roster.some(x=>x.name===n)),name=candidates[Math.floor(Math.random()*candidates.length)],genre=V1_GENRES[Math.floor(Math.random()*V1_GENRES.length)];c.cash-=1000;c.roster.push({name,genre,popularity:18+Math.floor(Math.random()*35),weeklyCost:75});v1AddFeed(c,`${name} signs to ${c.label.name} as the imprint’s first new voice.`,'♫');v1Net(c);persist();render();say(`${name} joins your roster.`);return}
 if(a==='form-group'){let choices=[c.stage,...(c.roster||[]).map(x=>x.name)];if(choices.length<2){say('Sign an artist first to form a group.');return}modal('Form a group','Choose a name for your crew.',`<div class="field"><label>Group name</label><input id="groupName" maxlength="32" placeholder="The name on the marquee"></div><p class="eyebrow">MEMBERS · ${choices.join(' · ')}</p>`,`<button class="btn btn-light" data-action="close">Cancel</button><button class="btn btn-purple" data-action="save-group">Form group</button>`);return}
 if(a==='save-group'){let name=$('#groupName')?.value.trim();if(!name){say('Give the group a name first.');return}c.groups.push({name,members:[c.stage,...(c.roster||[]).map(x=>x.name)]});c.energy=Math.max(0,c.energy-5);v1AddFeed(c,`${name} forms around ${c.stage} and the roster.`,'♬');v1Net(c);persist();$('#modal').remove();render();say(`${name} is official.`);return}
 if(a==='relationship'){let name=el.dataset.name,rel=c.relationships[name]||{score:0,rival:false};if(c.energy<8){say('You need 8 energy to network.');return}c.energy-=8;let rivalry=el.dataset.rival==='true';if(rivalry&&rel.rival){rel.rival=false;rel.score=Math.max(0,rel.score+8);say(`You and ${name} agree to move on.`)}else if(rivalry){rel.rival=true;rel.score=Math.max(-20,rel.score-8);c.heat=Math.min(99,c.heat+5);say(`${name} is now a chart rival. Heat is up.`)}else{rel.score=Math.min(100,rel.score+12);c.heat=Math.min(99,c.heat+2);say(`You build rapport with ${name}.`)}c.relationships[name]=rel;v1AddFeed(c,`${c.stage} ${rel.rival?'sparred with':'connected with'} ${name}.`,'◎');v1Net(c);persist();render();return}
 if(a.startsWith('event-')){let type=c.pendingEvent;if(a==='event-radio'&&c.cash>=300){c.cash-=300;c.heat=Math.min(99,c.heat+12);c.releases.forEach(r=>r.buzz+=8);say('Radio adds your music to rotation.')}else if(a==='event-radio')say('You need $300 for the radio push.');else if(a==='event-clapback'){c.heat=Math.min(99,c.heat+14);c.popularity=Math.min(100,c.popularity+2);say('The response makes headlines.')}else if(a==='event-benefit'&&c.energy>=15){c.energy-=15;c.popularity=Math.min(100,c.popularity+3);c.heat=Math.min(99,c.heat+3);say('The crowd showed love for the cause.')}else if(a==='event-benefit')say('Not enough energy to perform.');else if(a==='event-studio'&&c.cash>=250){c.cash-=250;c.energy=Math.min(100,c.energy+5);c.releases.forEach(r=>r.buzz+=4);say('The session is booked.')}else if(a==='event-studio')say('You need $250 for the session.');else say(a==='event-ignore'?'You stayed above the noise.':'Opportunity passed.');c.pendingEvent=null;v1Net(c);persist();$('#modal')?.remove();render();return}
 if(a==='radio'){if(c.energy<8){say('You need 8 energy.');return}c.energy-=8;v1BaseAction(a,el);v1Net(c);persist();render();return}
 if(a==='connect'){if(c.energy<6){say('You need 6 energy to network.');return}c.energy-=6;let name=el.dataset.name;c.relationships[name]=c.relationships[name]||{score:0,rival:false};c.relationships[name].score=Math.min(100,c.relationships[name].score+10);v1BaseAction(a,el);v1Net(c);persist();render();return}
 if(a==='producer'){if(c.energy<12){say('You need 12 energy.');return}if(c.cash<400){say('Not enough cash for this session.');return}c.energy-=12;v1BaseAction(a,el);v1Net(c);persist();render();return}
 if(a==='collab'){if(c.energy<12){say('You need 12 energy.');return}if(c.cash<250){say('Not enough cash to book the session.');return}c.energy-=12;v1BaseAction(a,el);v1Net(c);persist();render();return}
 if(a==='promo'){if(!c.releases.length){say('Release music before starting a campaign.');return}if(c.cash<350){say('Not enough cash to promote.');return}c.cash-=350;c.releases.slice(-1).forEach(r=>{r.buzz+=22;r.campaignWeeks=Math.max(r.campaignWeeks||0,3)});v1Net(c);persist();render();say('Campaign launched for your latest release.');return}
 if(a==='property'){v1BaseAction(a,el);v1Net(c);persist();render();return}
 if(['gig','buy','manager'].includes(a)){v1BaseAction(a,el);v1Net(c);persist();render();return}
 if(a==='release'){v1BaseAction(a,el);return}
 v1BaseAction(a,el);if(['save-look','save-outfit','equip'].includes(a)){v1Net(c);persist()}};
// One delegated listener already exists in game.js; replace its action dispatch target via the shared binding.
v1Migrate();
if(getSave()){render()}

